insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Cadre réglementaire','Quel est le rôle principal de l’AMF ?','Fixer les taux directeurs','Protéger l’épargne investie, informer les investisseurs et veiller au bon fonctionnement des marchés','Garantir tous les dépôts bancaires',1,'L’AMF protège l’épargne investie dans les instruments financiers, veille à l’information des investisseurs et au bon fonctionnement des marchés.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Cadre réglementaire','L’ACPR exerce principalement une mission de :','Supervision prudentielle des banques et assurances','Notation des obligations souveraines','Gestion de portefeuille',0,'L’ACPR supervise notamment les banques et les assurances sur le plan prudentiel et en matière de protection de la clientèle.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Cadre réglementaire','Une entreprise d’investissement peut fournir des services d’investissement si elle :','Dispose des autorisations nécessaires','Est uniquement immatriculée au registre du commerce','Publie ses comptes chaque mois',0,'La fourniture de services d’investissement est une activité réglementée soumise à autorisation.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Cadre réglementaire','La lutte contre le blanchiment vise notamment à :','Garantir un rendement minimum','Empêcher l’utilisation du système financier à des fins illicites','Supprimer tout paiement en espèces',1,'Les obligations LCB-FT visent à prévenir l’utilisation du système financier pour le blanchiment de capitaux et le financement du terrorisme.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Cadre réglementaire','Le principe de connaissance du client sert notamment à :','Adapter le service et identifier les risques','Déterminer le cours de Bourse','Fixer les taux d’imposition',0,'La connaissance du client permet de comprendre sa situation, ses objectifs, son expérience et ses risques afin d’adapter le service.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Cadre réglementaire','Un conflit d’intérêts doit être :','Ignoré s’il est temporaire','Identifié, prévenu ou géré et, si nécessaire, communiqué','Toujours interdit sans exception',1,'Les prestataires doivent identifier et gérer les conflits d’intérêts et prendre les mesures appropriées pour protéger les clients.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Cadre réglementaire','L’information fournie au client doit être :','Claire, exacte et non trompeuse','Uniquement commerciale','Réservée aux investisseurs professionnels',0,'Les communications adressées aux clients doivent être claires, exactes et non trompeuses.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Cadre réglementaire','La classification d’un client peut avoir un impact sur :','Le niveau de protection réglementaire','La devise de son compte uniquement','Le numéro ISIN des titres',0,'Le niveau de protection dépend notamment de la catégorie du client : non professionnel, professionnel ou contrepartie éligible.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Cadre réglementaire','Un abus de marché peut notamment prendre la forme :','D’une opération d’initié','D’un versement de dividende','D’une augmentation de capital',0,'Les abus de marché incluent notamment les opérations d’initiés, la divulgation illicite d’informations privilégiées et les manipulations de marché.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Cadre réglementaire','Une information privilégiée est une information :','Publique et générale','Précise, non publique et susceptible d’influencer sensiblement le cours','Toujours comptable',1,'Une information privilégiée est précise, non publique et susceptible d’avoir un effet sensible sur le cours si elle devenait publique.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Instruments financiers','Une action représente :','Une fraction du capital d’une société','Une créance certaine sur l’État','Un dépôt bancaire',0,'Une action est un titre de propriété représentant une fraction du capital d’une société.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Instruments financiers','Une obligation représente principalement :','Une créance sur l’émetteur','Un droit de vote systématique','Une part de fonds monétaire',0,'Une obligation est un titre de créance émis par une entreprise, un État ou un autre organisme.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Instruments financiers','Lorsque les taux d’intérêt montent, le prix d’une obligation à taux fixe tend généralement à :','Monter','Baisser','Rester toujours inchangé',1,'Il existe généralement une relation inverse entre taux de marché et prix des obligations à taux fixe.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Instruments financiers','Le dividende d’une action est :','Toujours garanti','Une distribution décidée selon les règles applicables par la société','Un remboursement du nominal',1,'Le dividende dépend des résultats et des décisions de distribution ; il n’est pas garanti.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Instruments financiers','Un OPC permet notamment :','Une gestion collective d’un portefeuille','De garantir tous les investissements','D’émettre de la monnaie',0,'Un organisme de placement collectif mutualise les capitaux de plusieurs investisseurs au sein d’un portefeuille.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Instruments financiers','Un ETF est généralement :','Un fonds coté en Bourse','Une obligation convertible','Un dépôt à terme',0,'Un ETF est un fonds coté qui cherche souvent à répliquer la performance d’un indice.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Instruments financiers','Un produit dérivé tire sa valeur :','D’un actif ou indicateur sous-jacent','Uniquement des bénéfices de l’émetteur','D’un taux d’épargne réglementé',0,'La valeur d’un dérivé dépend d’un actif, taux, indice ou autre variable sous-jacente.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Instruments financiers','Une option d’achat donne à son détenteur :','Le droit d’acheter le sous-jacent à certaines conditions','L’obligation d’acheter le sous-jacent','Le droit de recevoir un dividende garanti',0,'Une option call confère un droit, et non une obligation, d’acheter le sous-jacent selon les conditions prévues.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Instruments financiers','Le risque de crédit correspond au risque :','Que l’émetteur ou contrepartie ne respecte pas ses engagements','Que la Bourse ferme un jour férié','Que le client change de banque',0,'Le risque de crédit est le risque de défaut ou de dégradation de la qualité de crédit d’une contrepartie.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Instruments financiers','La diversification permet principalement de :','Supprimer tous les risques','Réduire certains risques spécifiques','Garantir un rendement positif',1,'La diversification réduit surtout le risque spécifique, mais ne supprime pas le risque de marché.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Marchés financiers','Le marché primaire correspond au marché :','Des émissions nouvelles de titres','Des échanges entre investisseurs après émission','Des devises uniquement',0,'Le marché primaire est celui sur lequel les titres sont émis pour la première fois.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Marchés financiers','Le marché secondaire correspond principalement :','À la négociation de titres déjà émis','À l’impression des billets','Aux prêts immobiliers',0,'Le marché secondaire permet l’échange de titres déjà existants entre investisseurs.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Marchés financiers','La liquidité d’un marché désigne notamment :','La facilité à acheter ou vendre sans trop influencer le prix','Le niveau des dividendes','La solvabilité de l’État',0,'Un marché liquide permet d’exécuter rapidement des transactions avec un impact limité sur les prix.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Marchés financiers','Un ordre au marché privilégie généralement :','La certitude d’exécution plutôt que le prix','La maîtrise absolue du prix','Le versement d’un coupon',0,'L’ordre au marché privilégie l’exécution rapide, mais le prix final n’est pas garanti.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Marchés financiers','Un ordre à cours limité permet :','De fixer un prix maximum à l’achat ou minimum à la vente','De garantir l’exécution','D’éviter tous les frais',0,'L’ordre limité permet de maîtriser le prix, mais pas de garantir l’exécution.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Marchés financiers','Le règlement-livraison correspond :','À l’échange des titres contre le paiement','À la fixation du coupon','À l’audit des comptes',0,'Le règlement-livraison matérialise le transfert des titres et le paiement correspondant.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Marchés financiers','La volatilité mesure principalement :','L’ampleur des variations de prix','Le dividende moyen','La valeur nominale',0,'La volatilité mesure la dispersion ou l’ampleur des variations du prix d’un actif.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Marchés financiers','Un indice boursier sert notamment à :','Mesurer l’évolution d’un ensemble de valeurs','Garantir un portefeuille','Déterminer le taux directeur',0,'Un indice représente la performance d’un panier de titres selon une méthodologie définie.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Marchés financiers','La capitalisation boursière d’une société correspond en principe à :','Cours de l’action × nombre d’actions','Chiffre d’affaires × bénéfice','Dividende × coupon',0,'La capitalisation correspond à la valeur de marché des actions en circulation.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Marchés financiers','Une chambre de compensation intervient notamment pour :','Réduire et gérer le risque de contrepartie sur certains marchés','Fixer les cours de clôture','Attribuer les codes ISIN',0,'La compensation centralisée contribue à gérer le risque de contrepartie entre intervenants.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Finance durable & ESG','Les critères ESG renvoient à :','Environnement, Social et Gouvernance','Épargne, Solvabilité et Garantie','Économie, Sécurité et Gestion',0,'ESG signifie Environnement, Social et Gouvernance.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Finance durable & ESG','L’objectif principal de la réglementation européenne sur les fournisseurs de notations ESG est de :','Fixer une note ESG unique','Renforcer transparence, indépendance et prévention des conflits d’intérêts','Interdire les méthodologies privées',1,'Le cadre européen vise notamment à accroître la transparence, l’indépendance et la gestion des conflits d’intérêts chez les fournisseurs de notations ESG.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Finance durable & ESG','Le greenwashing désigne :','Une présentation trompeuse ou exagérée du caractère durable d’un produit ou d’une activité','Une obligation verte','Une taxe sur le carbone',0,'Le greenwashing consiste à donner une image environnementale ou durable plus favorable que la réalité.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Finance durable & ESG','Une obligation verte est généralement destinée à financer :','Des projets à bénéfice environnemental','Uniquement des acquisitions d’actions','Des dividendes exceptionnels',0,'Les obligations vertes sont destinées à financer ou refinancer des projets contribuant à des objectifs environnementaux.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Finance durable & ESG','Le risque climatique peut être :','Physique ou de transition','Uniquement fiscal','Uniquement juridique',0,'Les risques climatiques incluent notamment les risques physiques et les risques liés à la transition vers une économie bas carbone.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Finance durable & ESG','La taxonomie européenne vise principalement à :','Définir un cadre de classification des activités économiques durables','Fixer les taux d’intérêt','Évaluer les diplômes des analystes',0,'La taxonomie européenne établit des critères permettant d’identifier certaines activités économiques considérées comme durables sur le plan environnemental.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Finance durable & ESG','Une politique d’investissement responsable peut intégrer :','Des critères ESG dans l’analyse et la sélection des actifs','Uniquement le rendement passé','Aucun facteur extra-financier',0,'L’investissement responsable peut intégrer les facteurs ESG au processus d’investissement.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Finance durable & ESG','Un indicateur d’empreinte carbone mesure principalement :','Les émissions de gaz à effet de serre associées à une activité ou un portefeuille','La volatilité historique','Le nombre d’actionnaires',0,'L’empreinte carbone vise à quantifier les émissions de gaz à effet de serre associées à une activité, une entreprise ou un portefeuille.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Finance durable & ESG','Le facteur « G » d’ESG concerne notamment :','La gouvernance d’entreprise','La géographie du siège','La garantie des dépôts',0,'La gouvernance couvre notamment la composition des organes dirigeants, l’éthique, les contrôles et les droits des actionnaires.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Finance durable & ESG','Le facteur « S » d’ESG couvre notamment :','Les conditions de travail et les droits humains','Les taux directeurs','Les indices boursiers',0,'Le pilier social porte notamment sur les salariés, les conditions de travail, la diversité et les droits humains.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Protection des clients','Le devoir de conseil suppose notamment de prendre en compte :','La situation, les objectifs et le profil du client','Uniquement l’âge','Uniquement le patrimoine financier',0,'Le conseil doit tenir compte de plusieurs dimensions du client, dont ses objectifs, sa situation, ses connaissances et sa tolérance au risque.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Protection des clients','Un client non professionnel bénéficie en principe :','D’un niveau de protection réglementaire élevé','D’aucune protection particulière','Du même régime qu’une contrepartie éligible',0,'Le client non professionnel bénéficie généralement du niveau de protection le plus élevé.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Protection des clients','L’évaluation de l’adéquation est particulièrement importante lorsqu’un prestataire fournit :','Un conseil en investissement ou une gestion de portefeuille','Un simple accès à un relevé bancaire','Un service postal',0,'L’adéquation vise à vérifier que la recommandation ou la gestion convient au client au regard de son profil.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Protection des clients','Le risque de perte en capital signifie :','Que l’investisseur peut récupérer moins que son investissement initial','Que tous les coupons sont annulés','Que le produit devient illégal',0,'Un produit avec risque de perte en capital peut conduire l’investisseur à récupérer moins que la somme investie.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Protection des clients','Les frais d’un produit financier doivent être :','Présentés de manière compréhensible au client','Toujours nuls','Communiqués uniquement après la vente',0,'Le client doit recevoir une information claire sur les coûts et frais applicables.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Protection des clients','Une réclamation client doit être :','Traitée selon une procédure organisée et dans les délais applicables','Ignorée si elle est orale','Transmise automatiquement au tribunal',0,'Les professionnels doivent disposer d’une procédure de traitement des réclamations.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Protection des clients','La confidentialité des informations du client implique notamment :','De protéger ses données et de limiter leur usage aux finalités autorisées','De publier son profil de risque','De transmettre ses données à tous les partenaires',0,'Les données clients doivent être protégées et utilisées conformément aux règles applicables.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Protection des clients','Un produit complexe exige généralement :','Une vigilance accrue sur l’information et la compréhension du client','Moins d’information','Aucune évaluation du client',0,'Plus un produit est complexe, plus les exigences de compréhension, d’information et d’évaluation sont importantes.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Protection des clients','Le profil de risque d’un client sert notamment à :','Apprécier sa capacité et sa volonté d’accepter des pertes','Calculer son impôt','Déterminer son numéro de compte',0,'Le profil de risque aide à déterminer le niveau de risque cohérent avec la situation et les objectifs du client.');
insert into public.questions(theme,question,option_a,option_b,option_c,correct_answer,explanation) values ('Protection des clients','Avant de souscrire un produit, le client doit notamment comprendre :','Ses caractéristiques, risques, coûts et horizon éventuel','Uniquement son nom commercial','Uniquement son rendement passé',0,'Une décision d’investissement éclairée suppose de comprendre le fonctionnement, les risques, les coûts et l’horizon du produit.');